-- GENERATED by scripts/build_seed_sql.py from app/permissions/seed/. Do not edit
-- by hand: change the JSON and rerun the script.
--
-- The initial roles, catalogue and grants. Together they reproduce exactly what
-- app/capabilities.py granted (tests/test_permissions_equivalence.py) and what
-- each service enforced in its own code (docs/ARCHITECTURE_ADMIN.md).
--
-- Apply after 004_permissions.sql. Safe to re-run: roles and services are only
-- inserted when missing, a service's catalogue only when it has never pushed a
-- manifest, and its grants only while nobody has edited them (grants_version 0).
-- So re-running never undoes what admins or deploys have changed since.
-- ── Roles ──────────────────────────────────────────────────────────────────────
insert into public.identity_roles
    (key, label, description, priority, is_superuser, exclusive_group)
values
    ('admin', 'Admin', 'Everything in every service, including user management and the admin console', 10, true, null),
    ('tech', 'Tech', 'Nearly everything; kept out of a few admin-only settings', 20, false, null),
    ('manager', 'Manager', 'Add, edit and publish properties in the CMS', 30, false, null),
    ('editor', 'Editor', 'Add, edit and publish properties in the CMS', 40, false, null),
    ('viewer', 'Viewer', 'Read-only access to the CMS', 50, false, null),
    ('lead_manager', 'Lead Manager', 'Every lead in Broker Tools; no CMS access', 60, false, null),
    ('presales', 'Pre-sales', 'Own pre-sales leads in Broker Tools', 70, false, 'desk'),
    ('sales', 'Sales', 'Own sales leads in Broker Tools', 80, false, 'desk')
on conflict (key) do nothing;

-- ── Services ───────────────────────────────────────────────────────────────────
insert into public.identity_services (key, name, description, is_system)
values
    ('broker_tools', 'Broker Tools', 'Leads, tasks and reports for the sales team', false),
    ('cms', 'CMS', 'Property listings, media and SEO for the public site', false),
    ('consultation_agent', 'Consultation Agent', 'Buyer consultations, recordings and itineraries', false),
    ('identity', 'AllSet Identity', 'Users, roles and permissions for every AllSet service', true),
    ('wa_automation', 'WhatsApp Automation', 'WhatsApp and Instagram console for leads', false)
on conflict (key) do nothing;

